// gnauralcity GCY1.6 (GCY-D17): the type checker's half of the host UI factory — the host's
// `tsconfig.hostkit.json`, generated from the same `HostUiConfig` its quasar.config.ts hands the quasar
// factory.
//
// Why a generated file and not just a base tsconfig to extend. A tsconfig that sets `paths` REPLACES the
// `paths` of the config it extends, it does not merge them (measured on TypeScript 5.7.3 and vue-tsc
// 2.2.12). Every host has `paths` of its own (the quasar twins, its own aliases), so a pin kept in a shared
// base would be dropped by the first host that adds one alias. Hence the chain:
//
//   <host ui>/tsconfig.json          — the host's include/exclude; extends ↓
//   <host ui>/tsconfig.hostkit.json  — GENERATED here: the whole `paths` (quasar twins, the host's own,
//                                      the shell's aliases, the pin); extends ↓
//   HostKitCore/ui/factory/tsconfig.base.json — the compiler options every host shares.
//
// The generated file lives in the host's ui/, so its relative `./node_modules/...` points into the
// host's own node_modules — the copy the bundler pins to. `write-host-tsconfig.ts` writes it. Whether a
// host's file is current is a WORKSPACE question (which hosts exist is the registry's data), so that
// lock lives with the registry's other checks, in the workspace's validate-qa.js; HostKitCore knows no
// host and its tests read nothing outside it (GCY-D1, GCY-D19).

import { join, relative } from 'node:path'
import { pathToFileURL } from 'node:url'

import { type HostUiConfig, QUASAR_TS_PATHS, SHELL_ALIASES, hostPins, mergeDistinct } from './host-ui'
import { pinnedTsPaths } from './pins'

/** The generated file's name, next to the host's tsconfig.json (which extends it). */
export const HOST_TSCONFIG_FILE = 'tsconfig.hostkit.json'

/** The shared compiler options, relative to the HostKitCore checkout. */
export const BASE_TSCONFIG = 'ui/factory/tsconfig.base.json'

/** This generator, relative to the HostKitCore checkout — named in the generated file's header. */
export const HOST_TSCONFIG_WRITER = 'ui/factory/write-host-tsconfig.ts'

const slash = (pathValue: string): string => pathValue.replace(/\\/g, '/')

/** A path from the host's ui/ to `target`, in the form tsconfig takes (forward slashes). */
const fromUi = (host: HostUiConfig, target: string): string => slash(relative(host.uiDir, target))

/** The host's whole tsconfig `paths`: quasar twins, the host's own, the shell's aliases, the pin. */
export function hostTsPaths(host: HostUiConfig): Record<string, string[]> {
  const shell = Object.fromEntries(
    Object.entries(SHELL_ALIASES).map(([name, rel]) => [`${name}/*`, [`${fromUi(host, join(host.hostKitDir, ...rel.split('/')))}/*`]]),
  )
  const own = Object.fromEntries(Object.entries(host.tsPaths).map(([name, targets]) => [name, [...targets]]))
  const quasar = Object.fromEntries(Object.entries(QUASAR_TS_PATHS).map(([name, targets]) => [name, [...targets]]))
  return mergeDistinct('tsconfig path', quasar, own, shell, pinnedTsPaths(hostPins(host), './node_modules'))
}

/** The full text of the host's generated tsconfig (LF; validate-qa.js compares with line ends normalised). */
export function renderHostTsconfig(host: HostUiConfig): string {
  const writer = fromUi(host, join(host.hostKitDir, ...HOST_TSCONFIG_WRITER.split('/')))
  const config = {
    extends: fromUi(host, join(host.hostKitDir, ...BASE_TSCONFIG.split('/'))),
    compilerOptions: { paths: hostTsPaths(host) },
  }
  return [
    `// GENERATED by HostKitCore/${HOST_TSCONFIG_WRITER} from \`hostUi\` in quasar.config.ts — do not edit.`,
    '// gnauralcity GCY1.6 (GCY-D17): the pin of one copy of shared libraries is ONE list',
    '// (HostKitCore/ui/factory/pins.ts + the host\'s modulePins); the bundler\'s aliases and these `paths`',
    '// are both derived from it. validate-qa.js (workspace root) reddens when this file is stale.',
    `// Regenerate from this directory: bun ${writer} .`,
    JSON.stringify(config, null, 2),
    '',
  ].join('\n')
}

/**
 * The `hostUi` exported by the quasar.config.ts in `uiDir` — for the generator and the workspace's
 * check, which name the directory; nothing here knows where hosts are.
 */
export async function loadHostUi(uiDir: string): Promise<HostUiConfig> {
  const file = join(uiDir, 'quasar.config.ts')
  const config = (await import(pathToFileURL(file).href)) as { hostUi?: HostUiConfig }
  if (config.hostUi === undefined) {
    throw new Error(`${file}: exports no \`hostUi\` — a host's quasar config is \`export const hostUi\` + \`export default hostQuasarConfig(hostUi)\` (GCY-D17)`)
  }
  return config.hostUi
}
